import{_ as n,C as r,c as o,o as i,a3 as s,G as a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"General settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/index.md","filePath":"master/general-settings/index.md","lastUpdated":1792041590000}'),l={name:"master/general-settings/index.md"};function u(h,e,g,m,d,c){const t=r("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=s('<h1 id="general-settings" tabindex="-1">General settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General settings&quot;">​</a></h1><p>The <strong>Settings</strong> app is where an administrator controls how Aureus ERP works for everyone. It holds your users, roles, companies and teams. It also holds the options that apply across all modules, such as the base currency and the look of the application.</p><blockquote><p><strong>In simple words:</strong> Settings is the control room for people, companies and system-wide options.</p></blockquote><p>Only administrators and users with the right role can open it.</p><h2 id="set-up-in-this-order" tabindex="-1">Set up in this order <a class="header-anchor" href="#set-up-in-this-order" aria-label="Permalink to &quot;Set up in this order&quot;">​</a></h2><ol><li>Install the modules you need. See <a href="./plugins.html">Plugins</a>.</li><li>Choose the base currency. See <a href="./companies/currency.html">Manage currency</a>.</li><li>Add your company. See <a href="./companies/companies.html">Companies</a>.</li><li>Create roles. See <a href="./users/roles.html">Roles</a>.</li><li>Create teams if you need group access. See <a href="./users/teams.html">Teams</a>.</li><li>Set the rules for new users, then create or invite users. See <a href="./users/manage-users.html">Manage users</a> and <a href="./users/users.html">Users</a>.</li><li>Set branding, custom fields and sequences. See <a href="./customization/branding.html">Branding</a>, <a href="./customization/custom-fields.html">Custom fields</a> and <a href="./customization/sequences.html">Sequences</a>.</li></ol><h2 id="top-tabs" tabindex="-1">Top tabs <a class="header-anchor" href="#top-tabs" aria-label="Permalink to &quot;Top tabs&quot;">​</a></h2><p>The app is called Settings, and its last tab is also called Settings. The tabs at the top of the screen are:</p><ul><li><strong>Roles:</strong> Define what each group of users may see and do. See <a href="./users/roles.html">Roles</a>.</li><li><strong>Companies:</strong> Add and edit the companies you work for. See <a href="./companies/companies.html">Companies</a>.</li><li><strong>Teams:</strong> Group users into teams. See <a href="./users/teams.html">Teams</a>.</li><li><strong>Users:</strong> Create users and invite new ones. See <a href="./users/users.html">Users</a>.</li><li><strong>Custom Fields:</strong> Add your own fields to records. See <a href="./customization/custom-fields.html">Custom fields</a>.</li><li><strong>Sequences:</strong> Control how document numbers are built. See <a href="./customization/sequences.html">Sequences</a>.</li><li><strong>Settings:</strong> Open the option pages described below.</li></ul><p><strong>Plugins</strong> is not a tab. It is its own menu in the main navigation.</p>',10)),a(t,{src:"/images1/general-settings/settings_top_tabs.png",alt:"Settings app with the top tabs Roles, Companies, Teams, Users, Custom Fields, Sequences and Settings"}),e[1]||(e[1]=s('<h2 id="the-general-group" tabindex="-1">The General group <a class="header-anchor" href="#the-general-group" aria-label="Permalink to &quot;The General group&quot;">​</a></h2><p>Click the <strong>Settings</strong> tab to open a menu on the left. The <strong>General</strong> group has these pages:</p><ul><li><strong>Manage Activities:</strong> Create and edit activity types. See <a href="./../getting-started/activities.html">Activities</a>.</li><li><strong>Manage Currency:</strong> Choose the base currency. See <a href="./companies/currency.html">Manage currency</a>.</li><li><strong>Manage Users:</strong> Set invitation, password reset and default values for new users. See <a href="./users/manage-users.html">Manage users</a>.</li><li><strong>Branding:</strong> Change logos, favicon and colors. See <a href="./customization/branding.html">Branding</a>.</li></ul><p>Each installed module can add its own group to this menu.</p>',4)),a(t,{src:"/images1/general-settings/settings_left_menu.png",alt:"Settings tab with the left menu showing the General group"}),e[2]||(e[2]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>You see only the pages your role allows. If a page is missing, ask an administrator to check your role.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./users/manage-users.html">Manage users</a></li><li><a href="./companies/currency.html">Manage currency</a></li><li><a href="./customization/branding.html">Branding</a></li><li><a href="./plugins.html">Plugins</a></li></ul>',3))])}const S=n(l,[["render",u]]);export{f as __pageData,S as default};
